const now = new Date().toISOString();
const stateKey = 'n8n_guided_flow';
function asObject(value) {
  if (!value) return {};
  if (typeof value === 'string') {
    try { return JSON.parse(value); } catch (e) { return {}; }
  }
  return typeof value === 'object' ? value : {};
}
function slug(value) {
  return String(value || '').trim().toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '');
}
function submittedEntries(item) {
  if (Array.isArray(item.submittedValues)) return item.submittedValues;
  const payload = item.rawPayload || {};
  const attrs = payload.message?.content_attributes || payload.content_attributes || {};
  const submitted = attrs.submitted_values || attrs.submittedValues || [];
  if (Array.isArray(submitted)) return submitted;
  if (submitted && typeof submitted === 'object') return Object.entries(submitted).map(([name, value]) => ({ name, value }));
  return submitted ? [{ value: submitted }] : [];
}
function firstSubmittedValue(entries) {
  const first = entries[0];
  if (!first) return '';
  if (typeof first === 'object') return first.value || first.payload || first.name || first.title || '';
  return first;
}
function collectFormData(entries) {
  const data = {};
  entries.forEach((entry, index) => {
    if (!entry || typeof entry !== 'object') return;
    const key = entry.name || entry.id || entry.key || `field_${index + 1}`;
    data[key] = entry.value ?? entry.answer ?? entry.text ?? '';
  });
  return data;
}
function stateWith(base, patch) {
  return { ...base, ...patch, updated_at: now };
}
function output(item, guidedAction, nextGuidedState, guidedMessageBody, extra = {}) {
  return [{ json: { ...item, guidedAction, nextGuidedState, guidedMessageBody, ...extra } }];
}
function menuBody(content, options) {
  return {
    content,
    message_type: 'outgoing',
    private: false,
    content_type: 'input_select',
    content_attributes: { items: options.map((option) => ({ title: option.text, value: option.id })) }
  };
}
function formBody(node) {
  const typeMap = { textarea: 'text_area', text_area: 'text_area', email: 'email', select: 'select', text: 'text' };
  return {
    content: node.prompt || 'Please provide the details below.',
    message_type: 'outgoing',
    private: false,
    content_type: 'form',
    content_attributes: {
      items: (node.fields || []).map((field) => ({
        name: field.id,
        label: field.label || field.prompt || field.id,
        type: typeMap[field.type] || 'text',
        placeholder: field.placeholder || '',
        required: field.required === true,
        options: Array.isArray(field.options) ? field.options.map((option) => ({ label: option.label || option.text, value: option.value || option.id || option.text })) : undefined
      }))
    }
  };
}
function textBody(content) {
  return { content, message_type: 'outgoing', private: false };
}
function validateFlow(flow) {
  return flow && typeof flow === 'object' && flow.entry && flow.nodes && typeof flow.nodes === 'object' && flow.nodes[flow.entry];
}

const item = $input.first().json;
const flow = item.guidedFlow || {};
const customAttributes = asObject(item.customAttributes);
const guidedState = asObject(customAttributes[stateKey]);
const baseState = {
  flow_version: flow.version || 1,
  conversation_id: item.conversationId,
  current_node: guidedState.current_node || flow.entry,
  path: Array.isArray(guidedState.path) ? guidedState.path : [],
  form_data: asObject(guidedState.form_data),
  llm_turns: Number(guidedState.llm_turns || 0),
  selected_option: guidedState.selected_option || null,
  mode: guidedState.mode || null,
  step: guidedState.step || null
};
function handoff(reason, nodeId, extra = {}) {
  const state = stateWith(baseState, { current_node: nodeId || baseState.current_node || flow.entry, mode: 'handoff', step: reason, last_action: reason, resolved: false, ...extra.state });
  return output(item, 'handoff', state, null, {
    action: 'handoff',
    intent: reason,
    confidence: 1,
    riskFlags: Array.from(new Set([...(item.guardrailRiskFlags || []), 'human_requested'])),
    knowledgeUsed: [],
    publicAnswer: '',
    labelSuggestions: Array.from(new Set([...(item.guardrailLabels || []), 'guided_flow', ...(extra.labels || [])])),
    privateSummary: extra.summary || `Guided flow handoff. reason=${reason} node=${nodeId || baseState.current_node} path=${state.path.join('>')} form_data=${JSON.stringify(state.form_data || {})}`
  });
}
function renderNode(nodeId, patch = {}) {
  const node = flow.nodes[nodeId];
  if (!node) return handoff('guided_flow_missing_node', nodeId, { labels: ['guided_flow_error'], summary: `Guided flow missing node: ${nodeId}` });
  const common = stateWith(baseState, { current_node: nodeId, mode: node.type, step: node.type, last_action: `show_${node.type}`, resolved: false, ...patch });
  if (node.type === 'options') return output(item, 'guided_reply', common, menuBody(node.prompt || 'Choose an option.', node.options || []));
  if (node.type === 'form') return output(item, 'guided_reply', common, formBody(node));
  if (node.type === 'text') {
    if (node.next && flow.nodes[node.next]?.type === 'options') {
      const nextNode = flow.nodes[node.next];
      const state = stateWith(common, { current_node: node.next, mode: 'options', step: 'options', last_action: 'show_text_with_options' });
      return output(item, 'guided_reply', state, menuBody([node.content || '', nextNode.prompt || 'Choose an option.'].filter(Boolean).join('\n\n'), nextNode.options || []));
    }
    return output(item, 'guided_reply', stateWith(common, { resolved: nodeId === 'resolved' }), textBody(node.content || 'Done.'));
  }
  if (node.type === 'llm') {
    const state = stateWith(common, { mode: 'llm', step: 'awaiting_custom', selected_option: patch.selected_option || baseState.selected_option || 'custom' });
    const enteringFromSelection = currentNodeId !== nodeId || submitted || patch.last_action === 'option_selected';
    if (enteringFromSelection) {
      return output(item, 'guided_reply', state, textBody(node.prompt || 'Please describe the issue in your own words.'));
    }
    return output(item, 'llm', stateWith(state, { step: 'llm_support' }), null, { guidedState: stateWith(state, { step: 'llm_support' }) });
  }
  if (node.type === 'human') return handoff('human_requested', nodeId, { labels: ['human_requested'], state: patch });
  return handoff('guided_flow_unknown_type', nodeId, { labels: ['guided_flow_error'], summary: `Unsupported guided flow node type: ${node.type}` });
}
function findOption(node, rawValue, textValue) {
  const options = Array.isArray(node?.options) ? node.options : [];
  const direct = String(rawValue || '').trim();
  const directSlug = slug(direct || textValue);
  return options.find((option) => option.id === direct || slug(option.id) === directSlug || slug(option.text) === directSlug);
}

if (!validateFlow(flow)) return handoff('guided_flow_invalid_config', flow.entry || 'unknown', { labels: ['guided_flow_error'], summary: 'Guided flow config is missing entry/nodes.' });
if ((item.guardrailRiskFlags || []).includes('human_requested')) return renderNode('human');

const entries = submittedEntries(item);
const submitted = firstSubmittedValue(entries);
const formData = collectFormData(entries);
const currentNodeId = baseState.current_node || flow.entry;
const currentNode = flow.nodes[currentNodeId] || flow.nodes[flow.entry];
const text = String(item.userText || '').trim();
const greetingOnly = /^(hi|hello|hey|start|help|menu)$/i.test(text) || !text;

if (item.interactiveContentType === 'form' && currentNode?.type === 'form' && Object.keys(formData).length) {
  const nextFormData = { ...baseState.form_data, [currentNodeId]: formData };
  const target = currentNode.submitTarget || currentNode.next || 'human';
  return renderNode(target, { form_data: nextFormData, path: [...baseState.path, `${currentNodeId}:submitted`], last_action: 'form_submitted' });
}

if (currentNode?.type === 'options') {
  const option = findOption(currentNode, submitted, text);
  if (option) {
    return renderNode(option.target, { selected_option: option.id, path: [...baseState.path, option.id], last_action: 'option_selected' });
  }
}

if (!guidedState.current_node || guidedState.mode === 'completed' || greetingOnly) return renderNode(flow.entry, { path: [], form_data: {}, selected_option: null, llm_turns: 0 });
if (currentNode?.type === 'llm' && text && !submitted) return renderNode(currentNodeId);
return renderNode(flow.entry, { path: [], selected_option: null });

const item = $input.first().json;
const now = new Date().toISOString();
const current = item.nextGuidedState || item.guidedState || {};
const cameFromLlm = item.guidedAction === 'llm' || current.mode === 'llm' || current.step === 'llm_support';
const llmTurns = Number(current.llm_turns || 0) + (cameFromLlm ? 1 : 0);
const handoff = item.action === 'handoff';
const nextGuidedState = {
  ...current,
  mode: handoff ? 'handoff' : 'llm',
  step: handoff ? (cameFromLlm ? 'llm_handoff' : (current.step || 'guided_handoff')) : 'llm_replied',
  selected_option: current.selected_option || 'custom_question',
  llm_turns: llmTurns,
  resolved: false,
  updated_at: now
};
const labelSuggestions = Array.from(new Set([...(item.labelSuggestions || []), 'guided_flow']));
const privateSummary = [
  item.privateSummary || 'No summary provided by AI Agent.',
  `guided_mode=${nextGuidedState.mode}`,
  `guided_step=${nextGuidedState.step}`,
  `guided_selected=${nextGuidedState.selected_option}`,
  `llm_turns=${llmTurns}`
].join(' | ');
return [{ json: { ...item, nextGuidedState, labelSuggestions, privateSummary, failedTurnCount: item.failedTurnCount } }];

const toolContext = {
  crm: 'TODO: replace no-op with CRM HTTP Request node when credentials exist.',
  order: 'TODO: replace no-op with order/status HTTP Request node when credentials exist.',
  status: 'TODO: replace no-op with status-page HTTP Request node when credentials exist.'
};
return [{ json: { ...$json, toolContext } }];

const upstream = $('Build AI Agent Input').first().json;
const res = $input.first().json;
const text = res.output || res.text || res.response || res.content || res.json || '';
let agent = null;
let parseFailed = false;
if (typeof text === 'object' && text !== null) agent = text;
else {
  try { agent = JSON.parse(String(text).trim().replace(/^```json\s*|\s*```$/g, '')); }
  catch (e) { parseFailed = true; }
}
if (parseFailed) agent = { answer: null, confidence: 0, needs_human: true, risk_flags: ['tool_failed'], labels: ['bot_escalated'], private_summary: 'AI Agent returned non-JSON output' };
return [{ json: { ...upstream, agentOutput: agent, agentParseFailed: parseFailed } }];

const upstream = $('Parse AI Agent Output').first().json;
let agent = upstream.agentOutput || {};
const risk = new Set(Array.isArray(agent.risk_flags) ? agent.risk_flags : []);
for (const flag of upstream.guardrailRiskFlags || []) risk.add(flag);
if (upstream.contextFailed) risk.add('tool_failed');
agent = { ...agent, risk_flags: Array.from(risk), labels: Array.from(new Set([...(Array.isArray(agent.labels) ? agent.labels : []), ...(upstream.guardrailLabels || [])])) };

const handoffFlags = ['refund','billing_dispute','legal','security','data_deletion','angry_customer','human_requested','credential_shared','tool_failed','unknown'];
const confidence = typeof agent.confidence === 'number' ? agent.confidence : 0;
const answer = typeof agent.answer === 'string' ? agent.answer.trim() : '';
const risky = agent.risk_flags.some((f) => handoffFlags.includes(f));
const shouldHandoff = agent.needs_human === true || confidence < 0.7 || risky || !answer || answer.length > 1200;
const action = shouldHandoff ? 'handoff' : 'reply';
const summary = typeof agent.private_summary === 'string' && agent.private_summary.trim() ? agent.private_summary.trim() : 'No summary provided by AI Agent.';
return [{ json: { ...upstream, action, intent: agent.intent || 'unknown', confidence, riskFlags: agent.risk_flags, knowledgeUsed: Array.isArray(agent.knowledge_used) ? agent.knowledge_used : [], publicAnswer: answer, privateSummary: [summary, `action=${action}`, `intent=${agent.intent || 'unknown'}`, `confidence=${confidence}`, `risk_flags=${agent.risk_flags.join(',')}`, `knowledge_used=${(Array.isArray(agent.knowledge_used) ? agent.knowledge_used : []).join(',')}`].join(' | '), labelSuggestions: agent.labels } }];

const staticData = $getWorkflowStaticData('global');
if (!staticData.failedTurns) staticData.failedTurns = {};
const item = $input.first().json;
const key = String(item.conversationId);
const failed = item.action === 'handoff' || Number(item.confidence || 0) < 0.75;
const count = failed ? Number(staticData.failedTurns[key] || 0) + 1 : 0;
staticData.failedTurns[key] = count;
const forceHandoff = count >= Number($env.FAILED_TURN_THRESHOLD || 2);
if (forceHandoff && item.action !== 'handoff') {
  return [{ json: { ...item, action: 'handoff', privateSummary: `${item.privateSummary} | forced_handoff_after_failed_turns=${count}`, labelSuggestions: Array.from(new Set([...(item.labelSuggestions || []), 'repeated_bot_failure'])) } }];
}
return [{ json: { ...item, failedTurnCount: count } }];
